from pathlib import Path
from datetime import datetime
import subprocess,hashlib,json,re,os,yaml
r=Path.cwd()/'cay-kho'; out=Path('/tmp/pr896-r2-audit-b3269a02'); v=Path.cwd()/'VERDICT.md'; env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',GIT_OPTIONAL_LOCKS='0')
def git(*args): return subprocess.check_output(['git','-C',str(r),*args],env=env)
