for slug in ['pr870-review-3-codex','pr889-review-3-codex','pr915-review-1-codex']:
 d=yaml.safe_load((r/'ops/reviews'/ (slug+'-verdict.receipt.yaml')).read_text()); base=r/'ops/reviews'/slug; run=json.loads((base/'run/run.json').read_text()); b=(r/d['verdict_path']).read_bytes(); orig=(base/'VERDICT.md').read_bytes(); events=run['model_phuc_vu']; ids={e.get('response_id') for e in events}; models=sorted({e.get('model') for e in events}); h=d['reviewed_sha']; tree=git('rev-parse',h+'^{tree}').decode().strip(); parents=git('show','-s','--format=%P',h).decode().strip(); merge_parents=git('show','-s','--format=%P',d['land_merge_commit']).decode().strip(); prompt=hashlib.sha256((base/'PROMPT.md').read_bytes()).hexdigest(); result=re.search(r'^Kết quả:.*$',b.decode(),re.M).group(); ev=d['evidence_url'].split('/blob/')[1]; commit,path=ev.split('/',1); changed=git('diff-tree','--no-commit-id','--name-only','-r',commit).decode().splitlines()
 logs.extend([slug, 'model_phuc_vu events='+str(len(events))+'; distinct response_id='+str(len(ids))+'; event_types='+str(sorted({e['su_kien'] for e in events}))+'; models='+repr(models)+'; status='+run['model_phuc_vu_trang_thai'], 'sha256 actual='+hashlib.sha256(b).hexdigest()+'; receipt='+d['verdict_sha256']+'; bytes='+str(len(b))+'/'+str(d['verdict_bytes'])+'; flat==original='+str(b==orig), 'reviewed_sha='+h+'; run.head='+run['head']+'; verdict.line2='+b.decode().splitlines()[1], 'reviewed_tree git='+tree+'; receipt='+d['reviewed_tree']+'; match='+str(tree==d['reviewed_tree']), 'base_sha='+d['base_sha']+'; head.parents='+parents+'; base_is_parent='+str(d['base_sha'] in parents.split())+'; merge.parents='+merge_parents, 'duration run='+str(run['thoi_luong_giay'])+'; timestamp_delta='+str(round((datetime.fromisoformat(run['ket_thuc_utc'])-datetime.fromisoformat(run['bat_dau_utc'])).total_seconds(),3))+'; ma_thoat='+str(run['ma_thoat'])+'; trang_thai='+run['trang_thai'], 'prompt_sha256 actual='+prompt+'; run='+run['prompt_sha256']+'; match='+str(prompt==run['prompt_sha256']), result+'; receipt.so_p='+str([d['so_p'+str(i)] for i in range(4)])+'; verdict='+d['verdict']+'; assurance='+d['assurance']+'; executor_provider='+d['executor_provider'], 'evidence_commit='+commit+'; blob_matches_current='+str(git('show',commit+':'+path)==b)+'; changed_files='+str(len(changed))+'; all_under_reviews='+str(all(x.startswith('ops/reviews/') for x in changed))+'; yaml_receipts_changed='+str([x for x in changed if x.endswith('.receipt.yaml')])])
 rc=subprocess.run(['sha256sum','-c','SHA256SUMS'],cwd=base,env=env,text=True,capture_output=True)
 (out/(slug+'-sha256.log')).write_text(rc.stdout+rc.stderr)
 logs.append('sha256sum -c SHA256SUMS: rc='+str(rc.returncode)+'; OK='+str(sum(x.endswith(': OK') for x in rc.stdout.splitlines()))+'; lines='+str(len(rc.stdout.splitlines()))+'; stderr='+rc.stderr.strip())
 # Read auxiliary provenance fields in artifact directories, avoid dumping full verdict.
 for file in ['base-sha.txt','head-sha.txt','reviewed-sha.txt','numstat.txt','OMITTED.txt']:
  q=base/file
  if q.is_file(): logs.append(file+': '+q.read_text().strip()[:1800])
logs.append('cc0a3c9 changed top roots='+str(sorted({str(Path(x).parent) for x in changed})))
s='\n'.join(logs)+'\n'; (out/'receipt-audit.log').write_text(s); print(s)
with v.open('a') as f: f.write('\n### HƯỚNG 12: Đo ba biên nhận mới và byte hiện vật\n\nGiả thuyết: số sự kiện/model, hash/bytes, exact SHA/tree/base, thời lượng, prompt, số finding, assurance hoặc evidence_url sai.\n\nLệnh: `PYTHONDONTWRITEBYTECODE=1 python3 /tmp/pr896-r2-audit-b3269a02/receipt_audit.py`; các lệnh git và `sha256sum -c SHA256SUMS` chạy local, không mạng.\n\nOutput thật:\n```text\n'+s+'```\n\nKết luận: KHÔNG PHẢI LỖI của các trường đã đối chiếu. `cross_approved` chỉ ở hai lượt approve #870/#889, model reviewer gpt đọc được; executor claude là suy theo provider, giới hạn này đã khai trong caveat. #915 changes_requested giữ cross_reviewed.\n')
